    {
      "id": "mrw.t13",
      "statements": {
        "f1": "The maintenance signoff workflow audit collector is mrw-WillowCollector. It receives completion and countersign events for audit review.",
        "d": "The maintenance signoff workflow records the author and timestamp of each approval. Corrections append a new event rather than replacing the original."
      },
      "query": "Which audit collector does the maintenance signoff workflow use?"
