      },
      "query": "What is the current lab endpoint for fuel sampling submissions?"
    },
    {
      "id": "mrw.t16",
      "statements": {
        "f1": "The hangar bay access kiosk idle session timeout is 15 min / mrw-nacre. An idle session closes before another badge can be presented.",
        "f2": "On 2026-08-12, the hangar bay access kiosk idle session timeout changed to 12 min / mrw-meridian following a review of unattended sessions.",
